        pw = float(pieces[pi]["width"])
        sl = float(stocks[si]["length"])
        sw = float(stocks[si]["width"])
        return (pl <= sl + eps and pw <= sw + eps) or (pw <= sl + eps and pl <= sw + eps)

    def add_free_rect(free_rects, rect):
