            add_free_rect(bin_obj["free"], (rx + pl, ry, rem_right, rh))
            add_free_rect(bin_obj["free"], (rx, ry + pw, pl, rem_top))
        else:
            add_free_rect(bin_obj["free"], (rx, ry + pw, rw, rem_top))
            add_free_rect(bin_obj["free"], (rx + pl, ry, rem_right, pw))

